  "hf-helenismo-22": { "tipo": "img", "src": "media/galeria/a10_jardin_epicuro_01.jpg", "t": "El Jardín de Epicuro", "alt": "Representación del Jardín de Epicuro como espacio de filosofía compartida", "pie": "El Jardín muestra la dimensión práctica y comunitaria de la clasificación de los deseos." },
