  "hf-metafisica-33": { "tipo": "img", "src": "media/retratos/museo/spinoza.jpg", "t": "Spinoza", "alt": "Retrato de Baruch Spinoza", "pie": "El retrato identifica al autor de la fórmula Deus sive Natura y de la Ética escrita con método geométrico." },
  "hf-metafisica-35": { "tipo": "crono", "id": "B-MOD-KRO-01", "pie": "Cronología del racionalismo y empirismo modernos para situar la respuesta de Spinoza a Descartes." },
