  "hf-posmodernidad-39": { "tipo": "img", "src": "media/galeria/kontsulta_medikoa_vienan_01.jpg", "t": "Consulta médica en Viena", "alt": "Consulta médica en la Viena de principios del siglo XX, con paciente y médico", "pie": "La consulta muestra al sujeto como objeto de discursos y saberes, en línea con la muerte del sujeto de Foucault." },
  "hf-posmodernidad-65": { "tipo": "mapa", "id": "map-ilustracion-modernidad", "pie": "El mapa conecta la herencia ilustrada con la crisis de la modernidad, el marco en el que Habermas defiende el proyecto inacabado." },
  "hf-posmodernidad-67": { "tipo": "img", "src": "media/galeria/c1_salon_filosofikoa_01.jpg", "t": "El salón filosófico", "alt": "Reunión de salón ilustrado con personas dialogando", "pie": "El salón ilustrado representa el espacio de diálogo público que Habermas propone como alternativa a la razón instrumental." },

