  "hf-existencialismo-4": { "tipo": "img", "src": "media/galeria/liburutegidistopikoa.jpg", "t": "La sombra del totalitarismo", "alt": "Imagen que evoca la vigilancia y el control totalitario sobre la vida pública y privada.", "pie": "El totalitarismo como trasfondo histórico que empuja al existencialismo a preguntarse por la dignidad del individuo." },
  "hf-existencialismo-9": { "tipo": "esquema", "id": "C8K-REL-01", "pie": "Esquema de la angustia y el salto de fe de Kierkegaard, antecedente directo del existencialismo." },
