  "hf-existencialismo-61": { "tipo": "img", "src": "media/retratos/museo/zambrano.jpg", "t": "María Zambrano", "alt": "Retrato de María Zambrano.", "pie": "La filósofa que propuso la razón poética para atender a las entrañas de la existencia." },
  "hf-existencialismo-67": { "tipo": "crono", "id": "C8-NB-CORPUS-02", "pie": "Cronograma que ordena a los autores existencialistas y su diálogo con la circunstancia." },

