  "hf-beauvoir-1": { "tipo": "img", "src": "media/retratos/museo/beauvoir.jpg", "t": "Simone de Beauvoir", "alt": "Retrato dibujado de Simone de Beauvoir", "pie": "El retrato sitúa a la autora que enmarca su pensamiento en el existencialismo ateo." },
  "hf-beauvoir-9": { "tipo": "crono", "id": "C9-KRO-01", "pie": "El cronograma muestra el feminismo como movimiento social con olas e hitos, no como lista de autoras." },
  "hf-beauvoir-22": { "tipo": "esquema", "id": "CdB-REL-01", "pie": "El esquema desglosa la alteridad, la construcción de la mujer y la libertad en Beauvoir." },
