  /* Historia de la Filosofía · Tema 27: La sociedad actual: retos del siglo XXI (Nous, 2026-10-25) */
  "hf-siglo21-7": { "tipo": "img", "src": "media/galeria/industria_lanaren_mundua_01.jpg", "t": "La industria cultural", "alt": "Imagen de la industria cultural: dominación mediante la atención, el consumo y el deseo", "pie": "La imagen muestra que la dominación no ocurre solo en la fábrica, sino también en el consumo y el deseo: ayuda a visualizar la tesis de Klein sobre las marcas como modos de vida." },
  "hf-siglo21-18": { "tipo": "esquema", "id": "C5A-REL-02", "pie": "El concepto de hegemonía cultural de Gramsci ayuda a entender cómo los medios moldean la opinión pública sin prohibir, presentando intereses de las élites como sentido común." },
  "hf-siglo21-21": { "tipo": "esquema", "id": "C5A-REL-01", "pie": "La teoría crítica de la Escuela de Fráncfort sitúa el problema de la industria cultural y de la ideología que el párrafo conecta con Chomsky." },
  "hf-siglo21-31": { "tipo": "img", "src": "media/galeria/med_a_08_kausen_katea.jpg", "t": "La dimensión del cuidado", "alt": "Imagen de relaciones de cuidado e interdependencia que sostienen la vida", "pie": "La imagen visibiliza las relaciones invisibles que sostienen la vida y la interdependencia: ilustra la propuesta de Herrero de poner la vida y los cuidados en el centro." },
  "hf-siglo21-39": { "tipo": "esquema", "id": "CdB-REL-02", "pie": "El esquema sitúa los debates de género posteriores a Beauvoir, incluida la performatividad de Butler, dentro de la justicia y las normas sociales." },
  "hf-siglo21-42": { "tipo": "esquema", "id": "C9-REL-01", "pie": "El esquema del feminismo contemporáneo ayuda a enmarcar el estudio de Preciado sobre el cuerpo, la tecnología y los regímenes político-sexuales." },
